'use strict';

const { ExprError } = require('./errors');

const PAIRS = new Set(['**', '//', '<=', '>=', '==', '!=']);
const SINGLES = new Set(['+', '-', '*', '/', '%', '<', '>', '(', ')', ',']);

/**
 * Create a lazy lexer: each call returns the next positioned token, ending with
 * repeated eof tokens. Laziness lets the parser report the leftmost error, so a
 * syntax error is not masked by an invalid character further right.
 */
function createLexer(source) {
  const space = /\s+/y;
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;
  return function next() {
    space.lastIndex = offset;
    if (space.test(source)) offset = space.lastIndex;
    if (offset >= source.length) return { type: 'eof', value: '', column: source.length + 1 };
    const column = offset + 1;
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      offset = number.lastIndex;
      return { type: 'number', value: Number(numeric[0]), column };
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      offset = identifier.lastIndex;
      return { type: 'identifier', value: name[0], column };
    }
    const pair = source.slice(offset, offset + 2);
    if (PAIRS.has(pair)) {
      offset += 2;
      return { type: 'operator', value: pair, column };
    }
    if (SINGLES.has(source[offset])) {
      offset += 1;
      return { type: 'operator', value: source[offset - 1], column };
    }
    throw new ExprError('Unexpected character', column);
  };
}

module.exports = { createLexer };

'use strict';

const { ExprError } = require('./errors');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
/** Built-in functions mapped to their maximum argument count (minimum is 1). */
const FUNCTIONS = new Map([['min', Infinity], ['max', Infinity], ['abs', 1]]);

/**
 * Parse a complete formula from a lexer into an AST. Nodes retain operator
 * columns. Flat chains are parsed with loops; errors are reported at the
 * leftmost point where the input stops being a valid prefix.
 */
function parse(next) {
  let token = next();
  const take = () => {
    const taken = token;
    token = next();
    return taken;
  };
  const isOperator = value => token.type === 'operator' && token.value === value;
  const expect = value => {
    if (!isOperator(value)) throw new ExprError(`Expected ${value}`, token.column);
    return take();
  };

  function comparison() {
    const first = sum();
    if (token.type !== 'operator' || !COMPARISONS.has(token.value)) return first;
    const operands = [first];
    const operators = [];
    while (token.type === 'operator' && COMPARISONS.has(token.value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (isOperator('+') || isOperator('-')) {
      const operator = take();
      left = { type: 'binary', operator, left, right: product() };
    }
    return left;
  }

  function product() {
    let left = unary();
    while (token.type === 'operator' && PRODUCTS.has(token.value)) {
      const operator = take();
      left = { type: 'binary', operator, left, right: unary() };
    }
    return left;
  }

  function unary() {
    const signs = [];
    while (isOperator('+') || isOperator('-')) signs.push(take());
    let node = power();
    for (let index = signs.length - 1; index >= 0; index -= 1) {
      node = { type: 'unary', operator: signs[index], operand: node };
    }
    return node;
  }

  function power() {
    const base = primary();
    if (!isOperator('**')) return base;
    const operator = take();
    return { type: 'binary', operator, left: base, right: unary() };
  }

  function primary() {
    if (token.type === 'number') return { type: 'number', value: take().value };
    if (token.type === 'identifier') {
      const name = take();
      if (!isOperator('(')) return { type: 'variable', name: name.value, column: name.column };
      const maxArgs = FUNCTIONS.get(name.value);
      if (maxArgs === undefined) throw new ExprError('Unknown function', name.column);
      take();
      if (isOperator(')')) throw new ExprError('Wrong argument count', name.column);
      const args = [comparison()];
      while (isOperator(',')) {
        if (args.length === maxArgs) throw new ExprError('Wrong argument count', name.column);
        take();
        args.push(comparison());
      }
      expect(')');
      return { type: 'call', name: name.value, args };
    }
    if (isOperator('(')) {
      take();
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (token.type !== 'eof') throw new ExprError('Unexpected token', token.column);
  return expression;
}

module.exports = { parse };

