'use strict';

const { ExprError } = require('./errors');

/** Python's float modulo (floatobject.c divmod), with a zero result as positive zero. */
function pythonMod(left, right) {
  const mod = left % right;
  if (!mod) return 0;
  return (right < 0) !== (mod < 0) ? mod + right : mod;
}

/** Python's float floor division (floatobject.c divmod), with a zero result as positive zero. */
function pythonFloorDiv(left, right) {
  const mod = left % right;
  let div = (left - mod) / right;
  if (mod && (right < 0) !== (mod < 0)) div -= 1;
  if (!div) return 0;
  let floorDiv = Math.floor(div);
  if (div - floorDiv > 0.5) floorDiv += 1;
  return floorDiv === 0 ? 0 : floorDiv;
}

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**':
      // Python: 1 ** y is 1 for any y, and (-1) ** ±inf is 1.
      if (left === 1 || (left === -1 && (right === Infinity || right === -Infinity))) return 1;
      return left ** right;
    case '//': return pythonFloorDiv(left, right);
    case '%': return pythonMod(left, right);
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
  while (frames.length) {
    const frame = frames[frames.length - 1];
    const node = frame.node;
