'use strict';
const { execFileSync } = require('node:child_process');
const { evaluate, ExprError } = require('./src/index');

const exprs = [
  '-7 // 2', '-7 % 3', '7 % -3', '7 // -2', '-7.5 // 2', '7.5 % -2', '0 // 5', '-0 % 5', '-6 // 3', '6 % -3',
  '-2 ** 2', '2 ** -1', '2 ** 3 ** 2', '2 ** -2 ** 2', '-2 ** -2', '(-2) ** 2', '- - 3', '+-+3',
  '1 < 2 < 3', '3 > 2 > 1', '1 < 3 < 2', '1 == 1 == 1', '(1 < 2) + 1', '(1 < 2) == 1', '2 * (3 > 1)',
  'min(1 < 2, 3)', 'max(0, 1 == 1)', 'min(3, 1, 2)', 'max(-1, -5)', 'abs(-3)', 'abs(1 < 2)', 'abs(-2 ** 2)',
  '1 + 2 * 3 - 4 / 2', '10 - 3 - 2', '2 * 3 % 4', '7 // 2 * 2 + 7 % 2', '1.5e-3 * 2', '.5 + 5.', '1 - -1',
  '-1e-20 % 3', '5 % -0.5', '1 ** (0/1)', '(1 < 2)', '-(1 < 2)', '2 ** 0.5', '-2 ** 0.5 * 2',
];
const py = JSON.parse(execFileSync('python', ['-c',
  'import json,sys\nout=[]\nfor e in json.load(sys.stdin):\n v=eval(e)\n out.append(v if isinstance(v,bool) else float(v))\nprint(json.dumps(out))'],
  { input: JSON.stringify(exprs) }).toString());
let bad = 0;
exprs.forEach((e, i) => {
  const got = evaluate(e);
  const want = py[i];
  const ok = typeof want === 'boolean' ? got === want : (typeof got === 'number' && Object.is(got === 0 ? 0 : got, want === 0 ? 0 : want));
  if (!ok) { bad++; console.log('MISMATCH', e, got, want); }
});

const col = (src, vars) => { try { evaluate(src, vars); return 'no error'; } catch (e) { if (!(e instanceof ExprError)) throw e; return e.column; } };
const errs = [
  ['1 +   ', 7], ['  )', 3], ['1 2', 3], ['  foo(1)', 3], ['abs(1, 2)', 1], ['min()', 1], ['foo(1 +)', 1],
  ['1 + $', 5], ['1 + ) $', 5], ['(1', 3], ['1 / 0', 3], ['  7 //  0', 6], ['5 %   (2-2)', 3], ['x + 1', 1],
  ['1 +  y', 6], ['min(1,)', 7], ['1 = 2', 3], ['1 < < 2', 5],
];
for (const [src, want] of errs) { const got = col(src); if (got !== want) { bad++; console.log('COLUMN', JSON.stringify(src), got, want); } }

let reads = 0;
const vars = { get a() { reads++; return 5; }, b: 1 };
col('foo(a)', vars); col('abs(a, a)', vars);
if (reads) { bad++; console.log('evaluated before syntax error'); }
reads = 0; evaluate('a < b < a', vars);
if (reads !== 1) { bad++; console.log('short-circuit reads', reads); }
reads = 0; evaluate('b < a < 9', vars);
if (reads !== 1) { bad++; console.log('shared operand reads', reads); }

const n = 200000;
for (const op of [' + ', ' * ', ' < ', ' - ', ' // ']) {
  const src = Array.from({ length: n }, (_, i) => String((i % 7) + 1)).join(op);
  const t = process.hrtime.bigint();
  evaluate(src);
  console.log(`${op.trim()} x${n}: ${Number(process.hrtime.bigint() - t) / 1e6}ms`);
}
console.log(bad ? `${bad} failures` : 'all checks pass');
